#!/usr/bin/env python3
"""Build a local-only frame-step viewer. No private pixels are embedded in the repository."""
from pathlib import Path
import argparse,json
p=argparse.ArgumentParser();p.add_argument('--metrics',type=Path,required=True);p.add_argument('--private-output',type=Path,required=True);a=p.parse_args();inv=json.loads((a.metrics/'inventory.json').read_text());data=[{k:v[k] for k in ['slug','file','decoded_frames','native_fps']} for v in inv['videos']]
html='''<!doctype html><meta charset="utf-8"><title>Private30fps reference study</title><style>body{background:#101725;color:#f4ead5;font:16px Arial;margin:24px}main{display:flex;gap:24px;flex-wrap:wrap}img{height:min(80vh,800px);width:auto;border:1px solid #777}button,select{font:inherit;padding:8px;margin:4px}input{width:100%;max-width:800px}output{display:block;margin:12px}a{color:#f7c764}p{max-width:780px}</style><h1>Private native-frame viewer</h1><p>Frame indices are zero-based. Every source is native30fps. JPEG inspection exports preserve original dimensions, with additional quality93 compression. Use source videos for final pixel comparisons. Keep this folder private.</p><select id="video"></select><select id="rate"><option>30</option><option>15</option><option>5</option><option>1</option></select><button id="play">Play</button><button data-step="-30">−1second</button><button data-step="-1">−1frame</button><button data-step="1">+1frame</button><button data-step="30">+1second</button><input id="seek" type="range" min="0" step="1"><output id="status"></output><main><img id="frame"><section><a id="overview">Overview sheet</a><p>Left/right arrows step one frame. Shift+arrow steps30frames. The live viewer is an inspection aid, not a realtime renderer guarantee.</p><a id="sheet">Current60frame contact sheet</a></section></main><script>const videos=DATA;const sel=document.querySelector('#video'),img=document.querySelector('#frame'),seek=document.querySelector('#seek'),status=document.querySelector('#status');let index=0,timer;for(const v of videos){const o=document.createElement('option');o.textContent=v.file;o.value=v.slug;sel.append(o)}const pad=n=>String(n).padStart(6,'0');function draw(){const v=videos.find(x=>x.slug===sel.value);index=Math.max(0,Math.min(v.decoded_frames-1,index));seek.max=v.decoded_frames-1;seek.value=index;img.src=v.slug+'/frames/'+pad(index)+'.jpg';status.textContent=v.slug+' · frame'+index+' · '+(index/30).toFixed(6)+'s · '+v.decoded_frames+' native frames';document.querySelector('#overview').href=v.slug+'/overview.jpg';const first=Math.floor(index/60)*60,last=Math.min(first+59,v.decoded_frames-1);document.querySelector('#sheet').href=v.slug+'/sheets/frames-'+pad(first)+'-'+pad(last)+'.jpg'}function stop(){clearInterval(timer);timer=null;document.querySelector('#play').textContent='Play'}sel.onchange=()=>{stop();index=0;draw()};seek.oninput=()=>{index=Number(seek.value);draw()};document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{stop();index+=Number(b.dataset.step);draw()});document.querySelector('#play').onclick=()=>{if(timer){stop();return}document.querySelector('#play').textContent='Pause';timer=setInterval(()=>{index++;draw();if(index>=Number(seek.max))stop()},1000/Number(document.querySelector('#rate').value))};document.querySelector('#rate').onchange=()=>{if(timer){stop();document.querySelector('#play').click()}};document.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();stop();index+=(e.key==='ArrowRight'?1:-1)*(e.shiftKey?30:1);draw()}});draw();</script>'''
a.private_output.mkdir(parents=True,exist_ok=True);(a.private_output/'index.html').write_text(html.replace('DATA',json.dumps(data)));print('Private frame-step viewer built.')
